import { useState } from 'react';
import styles from './trellis-app.module.css';

/**
 * Inline form for creating or editing a task (title + optional description).
 * @param props.onSubmit - called with the trimmed values
 * @param props.onCancel - optional cancel handler
 * @param props.initial - prefilled values when editing
 * @param props.placeholder - title placeholder
 */
export function TaskForm({
  onSubmit,
  onCancel,
  initial,
  placeholder = 'Task title',
  submitLabel = 'Add',
}: {
  onSubmit: (v: { title: string; description: string }) => void;
  onCancel?: () => void;
  initial?: { title: string; description?: string };
  placeholder?: string;
  submitLabel?: string;
}) {
  const [title, setTitle] = useState(initial?.title || '');
  const [description, setDescription] = useState(initial?.description || '');
  const [showDesc, setShowDesc] = useState(Boolean(initial?.description));

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({ title: title.trim(), description: description.trim() });
    if (!initial) {
      setTitle('');
      setDescription('');
    }
  };

  return (
    <form className={styles.taskForm} onSubmit={submit}>
      <input
        autoFocus
        className={styles.input}
        value={title}
        placeholder={placeholder}
        onChange={(e) => setTitle(e.target.value)}
        onKeyDown={(e) => e.key === 'Escape' && onCancel?.()}
      />
      {showDesc ? (
        <textarea
          className={styles.textarea}
          value={description}
          placeholder="Description (optional)"
          rows={2}
          onChange={(e) => setDescription(e.target.value)}
        />
      ) : null}
      <div className={styles.formActions}>
        {!showDesc ? (
          <button type="button" className={styles.linkBtn} onClick={() => setShowDesc(true)}>
            + Description
          </button>
        ) : <span />}
        <div className={styles.formButtons}>
          {onCancel ? (
            <button type="button" className={styles.ghostBtn} onClick={onCancel}>Cancel</button>
          ) : null}
          <button type="submit" className={styles.primaryBtn} disabled={!title.trim()}>{submitLabel}</button>
        </div>
      </div>
    </form>
  );
}
